27: // TiffStdOut.hpp
28: // ==============
29: // This file contains the standard output functionality for TIFF images. This
30: // is intended to provide easy output of TIFF image metadata and structure
31: // information to standard output for debugging and exploration.
32: 
33: #pragma once
34: 
35: #include "TiffImage.hpp"
36: 
37: #include <string>
38: #include <iostream>
39: #include <iomanip>
40: 
41: namespace TiffCraft {
42:   inline std::string toString(Tag tag)
43:   {
44:     switch (tag) {
45:       case TiffCraft::Tag::Null: return "Null";
46:       case TiffCraft::Tag::NewSubfileType: return "NewSubfileType";
47:       case TiffCraft::Tag::SubfileType: return "SubfileType";
48:       case TiffCraft::Tag::ImageWidth: return "ImageWidth";
49:       case TiffCraft::Tag::ImageLength: return "ImageLength";
50:       case TiffCraft::Tag::BitsPerSample: return "BitsPerSample";
51:       case TiffCraft::Tag::Compression: return "Compression";
52:       case TiffCraft::Tag::PhotometricInterpretation: return "PhotometricInterpretation";
53:       case TiffCraft::Tag::Thresholding: return "Thresholding";
54:       case TiffCraft::Tag::FillOrder: return "FillOrder";
55:       case TiffCraft::Tag::DocumentName: return "DocumentName";
56:       case TiffCraft::Tag::ImageDescription: return "ImageDescription";
57:       case TiffCraft::Tag::Make: return "Make";
58:       case TiffCraft::Tag::Model: return "Model";
59:       case TiffCraft::Tag::StripOffsets: return "StripOffsets";
60:       case TiffCraft::Tag::Orientation: return "Orientation";
61:       case TiffCraft::Tag::SamplesPerPixel: return "SamplesPerPixel";
62:       case TiffCraft::Tag::RowsPerStrip: return "RowsPerStrip";
63:       case TiffCraft::Tag::StripByteCounts: return "StripByteCounts";
64:       case TiffCraft::Tag::MinSampleValue: return "MinSampleValue";
65:       case TiffCraft::Tag::MaxSampleValue: return "MaxSampleValue";
66:       case TiffCraft::Tag::XResolution: return "XResolution";
67:       case TiffCraft::Tag::YResolution: return "YResolution";
68:       case TiffCraft::Tag::PlanarConfiguration: return "PlanarConfiguration";
69:       case TiffCraft::Tag::ResolutionUnit: return "ResolutionUnit";
70:       case TiffCraft::Tag::PageName: return "PageName";
71:       case TiffCraft::Tag::Software: return "Software";
72:       case TiffCraft::Tag::DateTime: return "DateTime";
73:       case TiffCraft::Tag::Artist: return "Artist";
74:       case TiffCraft::Tag::ColorMap: return "ColorMap";
75:       case TiffCraft::Tag::HalftoneHints: return "HalftoneHints";
76:       case TiffCraft::Tag::TileWidth: return "TileWidth";
77:       case TiffCraft::Tag::TileLength: return "TileLength";
78:       case TiffCraft::Tag::TileOffsets: return "TileOffsets";
79:       case TiffCraft::Tag::TileByteCounts: return "TileByteCounts";
80:       case TiffCraft::Tag::SampleFormat: return "SampleFormat";
81:       default: /* unknown tag */ break;
82:     }
83:     char buf[8] = "0x0000";
84:     std::snprintf(buf, sizeof(buf), "0x%04X", static_cast<uint16_t>(tag));
85:     return buf;
86:   }
87: 
88:   inline std::string_view toString(Type type) {
89:     switch (type) {
90:       case TiffCraft::Type::BYTE:      return "BYTE";
91:       case TiffCraft::Type::ASCII:     return "ASCII";
92:       case TiffCraft::Type::SHORT:     return "SHORT";
93:       case TiffCraft::Type::LONG:      return "LONG";
94:       case TiffCraft::Type::RATIONAL:  return "RATIONAL";
95:       case TiffCraft::Type::SBYTE:     return "SBYTE";
96:       case TiffCraft::Type::UNDEFINED: return "UNDEFINED";
97:       case TiffCraft::Type::SSHORT:    return "SSHORT";
98:       case TiffCraft::Type::SLONG:     return "SLONG";
99:       case TiffCraft::Type::SRATIONAL: return "SRATIONAL";
100:       case TiffCraft::Type::FLOAT:     return "FLOAT";
101:       case TiffCraft::Type::DOUBLE:    return "DOUBLE";
102:       default:                         return "!UNKNOWN";
103:     }
104:   }
105: 
106:   inline std::ostream& operator<<(std::ostream& os, TiffCraft::Tag tag) {
107:   return os << TiffCraft::toString(tag);
108: }
109: 
110:   inline std::ostream& operator<<(std::ostream& os, TiffCraft::Type type) {
111:   return os << TiffCraft::toString(type);
112: }
113: 
114:   inline std::ostream& operator<<(std::ostream& os, const TiffCraft::TiffImage::Header& header) {
115:   os << "TIFF Header:\n"
116:      << " - Byte Order: " << (header.byteOrder() == std::endian::little ? "Little Endian" : "Big Endian") << "\n"
117:      << " - First IFD Offset: " << header.firstIFDOffset() << "\n"
118:      << " - Equals Host Byte Order: " << (header.equalsHostByteOrder() ? "Yes" : "No") << "\n";
119:   return os;
120: }
121: 
122:   inline std::ostream& operator<<(std::ostream& os, const TiffCraft::TiffImage::IFD::Entry& entry) {
123:   os << "Tag: " << entry.tag() << "; "
124:      << "Type: " << entry.type() << "; "
125:      << "Count: " << entry.count() << ": "
126:      << "Value:";
127:   if (entry.type() == Type::ASCII) {
128:     // For ASCII type, print as a string
129:     os << " " << std::string(reinterpret_cast<const char*>(entry.values()), entry.bytes() - 1);
130:   } else {
131:     for (int i = 0; i < entry.count(); ++i) {
132:       const std::byte* value = entry.values() + i * TiffCraft::typeBytes(entry.type());
133:       switch (entry.type()) {
134:         case Type::BYTE:
135:           os << " " << static_cast<int>(*reinterpret_cast<const TypeTraits_t<Type::BYTE>*>(value));
136:           break;
137:         case Type::SHORT:
138:           os << " " << *reinterpret_cast<const TypeTraits_t<Type::SHORT>*>(value);
139:           break;
140:         case Type::LONG:
141:           os << " " << *reinterpret_cast<const TypeTraits_t<Type::LONG>*>(value);
142:           break;
143:         case Type::RATIONAL: {
144:           const auto* rational = reinterpret_cast<const TypeTraits_t<Type::RATIONAL>*>(value);
145:           os << " " << rational->numerator << "/" << rational->denominator;
146:           break;
147:         }
148:         case Type::SBYTE:
149:           os << " " << static_cast<int>(*reinterpret_cast<const TypeTraits_t<Type::SBYTE>*>(value));
150:           break;
151:         case Type::UNDEFINED: {
152:           const auto* undefined = reinterpret_cast<const TypeTraits_t<Type::UNDEFINED>*>(value);
153:           os << " 0x" << std::hex << std::setw(2) << std::setfill('0')
154:              << static_cast<int>(*undefined) << std::dec << std::setw(1) <<std::setfill(' ');
155:           break;
156:         }
157:         case Type::SSHORT:
158:           os << " " << *reinterpret_cast<const TypeTraits_t<Type::SSHORT>*>(value);
159:           break;
160:         case Type::SLONG:
161:           os << " " << *reinterpret_cast<const TypeTraits_t<Type::SLONG>*>(value);
162:           break;
163:         case Type::SRATIONAL: {
164:           const auto* rational = reinterpret_cast<const TypeTraits_t<Type::SRATIONAL>*>(value);
165:           os << " " << rational->numerator << "/" << rational->denominator;
166:           break;
167:         }
168:         case Type::FLOAT:
169:           os << " " << *reinterpret_cast<const TypeTraits_t<Type::FLOAT>*>(value);
170:           break;
171:         case Type::DOUBLE:
172:           os << " " << *reinterpret_cast<const TypeTraits_t<Type::DOUBLE>*>(value);
173:           break;
174:         default:
175:           os << " <Unsupported Type>";
176:       }
177:       if (i > 5) {
178:         // if there are more than 5 values, skip the rest
179:         os << " ...";
180:         break;
181:       }
182:     }
183:   }
184:   os << "\n";
185:   return os;
186: }
187: 
188:   inline std::ostream& operator<<(std::ostream& os, const TiffCraft::TiffImage::IFD& ifd) {
189:   struct AutoRestore {
190:     std::ostream& os_;
191:     std::ios_base::fmtflags flags_;
192:     AutoRestore(std::ostream& os) : os_(os), flags_(os.flags()) {}
193:     ~AutoRestore() { os_.flags(flags_); }
194:   } autoRestore(os);
195: 
196:   os << "TIFF IFD:\n"
197:      << "  Entry count: " << ifd.entries().size() << "\n";
198:   int i = 0;
199:   for (const auto& entry : ifd.entries()) {
200:     os << std::setw(4) << i++ << "# " << entry.second;
201:   }
202:   return os;
203: }
204: 
205:   inline std::ostream& operator<<(std::ostream& os, const TiffCraft::TiffImage& image) {
206:   struct AutoRestore {
207:     std::ostream& os_;
208:     std::ios_base::fmtflags flags_;
209:     AutoRestore(std::ostream& os) : os_(os), flags_(os.flags()) {}
210:     ~AutoRestore() { os_.flags(flags_); }
211:   } autoRestore(os);
212: 
213:   os << "TIFF IMAGE START -----------------------\n"
214:      << image.header()
215:      << "IFD count: " << image.ifds().size() << "\n";
216:   for (int i = 0; i < image.ifds().size(); ++i) {
217:     os << std::setw(2) << i << ") " << image.ifds()[i];
218:   }
219:   os << "TIFF IMAGE END -------------------------\n";
220:   return os;
221: }
222: 
223: } // namespace TiffCraft

