140: std::ostream& write_IFD(
141:   std::ostream& os,
142:   const std::vector<TiffImage::IFD::Entry>& entries,
143:   bool mustSwap = false)
144: {
145:   // We write the IFD first, and the entry data afterwards. Therefore, we need
146:   // calculate the offsets of the entries first.
147:   const uint32_t IFD_bytes = 2 + 12 * entries.size(); // 2 bytes for the count,
148:                                                       // and 12 bytes per entry
149: 
150:   // Current position in the stream
151:   std::streampos currentPos = os.tellp();
152: 
153:   uint32_t nextOffset = IFD_bytes + static_cast<uint32_t>(currentPos);
154:   std::vector<uint32_t> offsets;
155:   offsets.reserve(entries.size());
156:   for (const auto& entry : entries) {
157:     if (entry.bytes() > 4) {
158:       // If the entry value does not fit in 4 bytes, we need to write it at a later offset
159:       offsets.emplace_back(nextOffset);
160:       nextOffset += entry.bytes();
161:     }
162:     else {
163:       // If the entry value fits in 4 bytes, we can write it directly
164:       offsets.emplace_back(0);
165:     }
166:   }
167: 
168:   // Write the number of entries
169:   writeValue(os, static_cast<uint16_t>(entries.size()), mustSwap);
170: 
171:   // Write the entries
172:   for (const auto& entry : entries) {
173:     write_IFD_entry(os, entry.tag(), entry.type(), entry.count(),
174:       entry.values(), offsets[&entry - &entries[0]], mustSwap);
175:   }
176: 
177:   return os;
178: }
