31: 
32: #include <tiffcraft/TiffImage.hpp>
33: #include <iostream>
34: 
35: int main(int argc, char* argv[]) {
36:   if (argc < 2) {
37:     std::cerr << "Usage: " << argv[0] << " <image.tiff>" << std::endl;
38:     return 1;
39:   }
40: 
41:   std::cout << "TiffCraft version " << TiffCraft::version() << std::endl;
42:   std::cout << "Loading image: " << argv[1] << std::endl;
43: 
44:   TiffCraft::load(argv[1],
45:     [](const TiffCraft::TiffImage::Header& header,
46:         const TiffCraft::TiffImage::IFD& ifd,
47:         TiffCraft::TiffImage::ImageData imageData) {
48:       std::cout << "Loaded IFD with " << ifd.entries().size()
49:                 << " entries." << std::endl;
50: 
51:       size_t totalBytes = 0;
52:       for (const auto& vec : imageData) {
53:           totalBytes += vec.size();
54:       }
55:       std::cout << "Image data bytes: " << totalBytes << std::endl;
56: 
57:       auto readDimension = [](const TiffCraft::TiffImage::IFD& ifd, TiffCraft::Tag tag) -> uint32_t {
58:         const auto& entry = ifd.getEntry(tag);
59:         switch (entry.type()) {
60:           case TiffCraft::Type::SHORT: return entry.values<uint16_t>()[0];
61:           case TiffCraft::Type::LONG:  return entry.values<uint32_t>()[0];
62:           default: throw std::runtime_error("Unsupported ImageWidth/ImageLength entry type");
63:         }
64:       };
65:       std::cout << "Image width: "
66:                 << readDimension(ifd, TiffCraft::Tag::ImageWidth)
67:                 << std::endl;
68:       std::cout << "Image height: "
69:                 << readDimension(ifd, TiffCraft::Tag::ImageLength)
70:                 << std::endl;
71: 
72:       // Add your own image processing code here
73: 
74:     });
75: 
76:   return 0;
77: }
